package com.fluxisai.crm;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*; import java.util.*; import com.fluxisai.common.error.ConflictException; import com.fluxisai.common.security.CurrentUser; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension;
@ExtendWith(MockitoExtension.class) class CompanyServiceTest { static final UUID USER=UUID.fromString("11111111-1111-1111-1111-111111111111"); @Mock CompanyRepository repository; @Mock CurrentUser currentUser; @InjectMocks CompanyService service; @BeforeEach void setup(){when(currentUser.id()).thenReturn(USER);} @Test void createsCompanyScopedToCurrentUserAndTrimsName(){when(repository.save(any())).thenAnswer(i->i.getArgument(0)); var response=service.create(new CompanyRequest("  Acme  ","https://acme.test","Tech",null)); var captor=ArgumentCaptor.forClass(Company.class); verify(repository).save(captor.capture()); assertEquals(USER,captor.getValue().getUserId()); assertEquals("Acme",response.name());} @Test void rejectsDuplicateCompanyName(){when(repository.existsByUserIdAndNameIgnoreCase(USER,"Acme")).thenReturn(true); assertThrows(ConflictException.class,()->service.create(new CompanyRequest("Acme",null,null,null))); verify(repository,never()).save(any());} }
